if frappe.request:
    # الحصول على عنوان IPv4 للعميل
    # نتحقق أولاً من X-Forwarded-For في حالة وجود بروكسي، وإلا نستخدم remote_addr
    client_ip = frappe.request.headers.get('X-Forwarded-For') 
    
    if not client_ip:
        client_ip = frappe.request.remote_addr

    # معالجة الحالة التي يكون فيها أكثر من IP (مفصولة بفاصلة)
    if client_ip and ',' in client_ip:
        client_ip = client_ip.split(',')[0].strip()
        
    doc.ip_device = client_ip

specs = frappe.get_all(
    "User Permission",
    {"user": user, "allow": "Specialization"},
